const page = `<!doctype html>
<html lang="ja">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ffffff"><title>ChorusDBJP</title>
<style>
:root{font-family:"Noto Sans JP","Hiragino Sans",system-ui,sans-serif;color:#171717;background:#f7f7f5}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button{cursor:pointer}.top{height:58px;background:#fff;border-bottom:1px solid #ddd;display:flex;align-items:center}.top-inner{width:min(1160px,100%);margin:auto;padding:0 20px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:19px;font-weight:800;letter-spacing:-.03em}.brand span{color:#2463eb}.count{font-size:13px;color:#666}.hero{background:#fff;border-bottom:1px solid #e2e2e2}.hero-inner{width:min(1160px,100%);margin:auto;padding:42px 20px 34px}.hero h1{font-size:32px;line-height:1.35;margin:0 0 8px;letter-spacing:-.04em}.hero p{margin:0 0 24px;color:#666}.searchbox{display:flex;max-width:760px;height:52px;border:2px solid #222;background:#fff}.searchbox input{flex:1;border:0;outline:0;padding:0 16px;font-size:16px}.searchbox button{width:88px;border:0;background:#222;color:#fff;font-weight:700}.layout{width:min(1160px,100%);margin:auto;padding:28px 20px 60px;display:grid;grid-template-columns:210px 1fr;gap:34px}.filters h2{font-size:13px;margin:0 0 14px;color:#777}.filter{border-top:1px solid #ddd;padding:16px 0}.filter label{display:block;font-size:13px;font-weight:700;margin-bottom:8px}.filter select{width:100%;border:1px solid #bbb;background:#fff;border-radius:0;padding:9px}.reset{border:0;background:none;padding:0;color:#2463eb;font-size:13px}.result-head{display:flex;justify-content:space-between;align-items:center;padding:0 0 12px;border-bottom:2px solid #222}.result-head strong{font-size:15px}.sort-mobile{display:none}.list{background:#fff}.row{display:grid;grid-template-columns:minmax(220px,1.8fr) minmax(150px,1fr) 110px 110px 24px;gap:18px;align-items:center;padding:17px 14px;border-bottom:1px solid #e5e5e5;cursor:pointer}.row:hover{background:#f5f7fb}.title{font-size:16px;font-weight:700}.author{font-size:13px;color:#666;line-height:1.55}.badge{font-size:12px;color:#444}.level{font-size:12px;font-weight:700}.level i{display:inline-block;width:7px;height:7px;background:#2463eb;margin-right:3px}.arrow{color:#999;font-size:20px}.empty{padding:50px;text-align:center;color:#777;background:#fff}dialog{width:min(560px,calc(100% - 28px));border:0;padding:0;box-shadow:0 24px 80px rgba(0,0,0,.3)}dialog::backdrop{background:rgba(0,0,0,.48)}.modal-head{display:flex;justify-content:space-between;align-items:start;padding:24px;border-bottom:1px solid #ddd}.modal-head h2{margin:0;font-size:23px}.close{border:0;background:none;font-size:25px;line-height:1}.modal-body{padding:22px 24px 26px}.detail{display:grid;grid-template-columns:100px 1fr;gap:11px 16px;margin:0}.detail dt{color:#777;font-size:13px}.detail dd{margin:0}.note{margin-top:20px;padding:12px;background:#f3f3f1;font-size:12px;color:#666;line-height:1.6}@media(max-width:760px){.hero-inner{padding-top:30px}.hero h1{font-size:25px}.layout{display:block;padding:18px 14px 50px}.filters{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:18px}.filters h2{grid-column:1/-1;margin:0}.filter{border:0;padding:0}.filter:last-of-type{display:none}.reset{grid-column:1/-1;text-align:left}.result-head{padding-bottom:10px}.sort-mobile{display:block;border:1px solid #bbb;background:#fff;padding:7px}.row{grid-template-columns:1fr auto;padding:16px 12px;gap:8px}.row .author{grid-column:1}.row .badge,.row .level{grid-row:1/3;display:none}.row .arrow{grid-column:2;grid-row:1/3;align-self:center}.searchbox button{width:72px}.top-inner{padding:0 14px}}
</style>
</head>
<body>
<header class="top"><div class="top-inner"><div class="brand">ChorusDB<span>JP</span></div><div id="total" class="count">読み込み中</div></div></header>
<section class="hero"><div class="hero-inner"><h1>歌いたい合唱曲を探す</h1><p>曲名、作詞者、作曲者から検索できます。</p><div class="searchbox"><input id="query" type="search" placeholder="例：旅立ちの日に、木下牧子"><button id="searchButton">検索</button></div></div></section>
<main class="layout"><aside class="filters"><h2>絞り込み</h2><div class="filter"><label for="voicing">編成</label><select id="voicing"><option value="">すべて</option></select></div><div class="filter"><label for="difficulty">難易度</label><select id="difficulty"><option value="">すべて</option><option value="1">1</option><option value="2">2</option><option value="3">3</option><option value="4">4</option><option value="5">5</option></select></div><div class="filter"><label for="sort">並び順</label><select id="sort"><option value="kana">曲名順</option><option value="difficulty-asc">難易度が低い順</option><option value="difficulty-desc">難易度が高い順</option><option value="composer">作曲者順</option></select></div><button id="reset" class="reset">条件をリセット</button></aside><section><div class="result-head"><strong id="status">読み込み中</strong><select id="sortMobile" class="sort-mobile"><option value="kana">曲名順</option><option value="difficulty-asc">難易度↑</option><option value="difficulty-desc">難易度↓</option><option value="composer">作曲者順</option></select></div><div id="results" class="list"></div></section></main>
<dialog id="detail"><div class="modal-head"><h2 id="detailTitle"></h2><button id="close" class="close" aria-label="閉じる">×</button></div><div id="detailBody" class="modal-body"></div></dialog>
<script>
const state={songs:[]};const q=document.getElementById('query'),v=document.getElementById('voicing'),d=document.getElementById('difficulty'),s=document.getElementById('sort'),sm=document.getElementById('sortMobile'),status=document.getElementById('status'),results=document.getElementById('results'),detail=document.getElementById('detail');
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function dots(n){return Array.from({length:5},(_,i)=>'<i style="opacity:'+(i<n?1:.18)+'"></i>').join('')}
function rows(song){const by=[song.lyricist?'作詞 '+song.lyricist:'',song.composer?'作曲 '+song.composer:''].filter(Boolean).join(' / ');return '<article class="row" tabindex="0" data-id="'+esc(song.id)+'"><div><div class="title">'+esc(song.title)+'</div><div class="author">'+esc(by||'作者情報 未確認')+'</div></div><div class="badge">'+esc(song.voicing||'編成未確認')+'</div><div class="badge">'+esc(song.accompaniment||'')+'</div><div class="level">'+dots(Number(song.difficulty||0))+'</div><div class="arrow">›</div></article>'}
function items(){const text=q.value.trim().toLowerCase();const a=state.songs.filter(x=>{const h=[x.title,x.title_kana,x.lyricist,x.composer,x.arranger].join(' ').toLowerCase();return(!text||h.includes(text))&&(!v.value||x.voicing===v.value)&&(!d.value||String(x.difficulty)===d.value)});const mode=s.value;if(mode==='difficulty-asc')a.sort((x,y)=>(x.difficulty||99)-(y.difficulty||99));else if(mode==='difficulty-desc')a.sort((x,y)=>(y.difficulty||0)-(x.difficulty||0));else if(mode==='composer')a.sort((x,y)=>String(x.composer||'').localeCompare(String(y.composer||''),'ja'));else a.sort((x,y)=>String(x.title_kana||x.title).localeCompare(String(y.title_kana||y.title),'ja'));return a}
function render(){const a=items();status.textContent=a.length+'曲';results.innerHTML=a.length?a.map(rows).join(''):'<div class="empty">該当する曲がありません</div>'}
function openSong(id){const x=state.songs.find(y=>y.id===id);if(!x)return;document.getElementById('detailTitle').textContent=x.title;const data=[['読み',x.title_kana],['作詞',x.lyricist],['作曲',x.composer],['編曲',x.arranger],['編成',x.voicing],['伴奏',x.accompaniment],['難易度',x.difficulty?x.difficulty+' / 5':null],['出版社',x.publisher]].filter(z=>z[1]);document.getElementById('detailBody').innerHTML='<dl class="detail">'+data.map(z=>'<dt>'+esc(z[0])+'</dt><dd>'+esc(z[1])+'</dd>').join('')+'</dl><div class="note">未検証の項目があります。楽譜版によって編成や難易度が異なる場合があります。</div>';detail.showModal();history.replaceState(null,'','#song='+encodeURIComponent(id))}
async function load(){let r=await fetch('/api/songs');let data=await r.json();state.songs=Array.isArray(data)?data:[];if(state.songs.length<190){await fetch('/api/setup/seed-extra',{method:'POST'});r=await fetch('/api/songs?fresh='+Date.now());data=await r.json();state.songs=Array.isArray(data)?data:[]}document.getElementById('total').textContent=state.songs.length+'曲収録';[...new Set(state.songs.map(x=>x.voicing).filter(Boolean))].sort().forEach(x=>{const o=document.createElement('option');o.value=o.textContent=x;v.appendChild(o)});render();const m=location.hash.match(/^#song=(.+)$/);if(m)openSong(decodeURIComponent(m[1]))}
[q,v,d,s].forEach(e=>e.addEventListener(e===q?'input':'change',()=>{sm.value=s.value;render()}));sm.addEventListener('change',()=>{s.value=sm.value;render()});document.getElementById('searchButton').onclick=render;document.getElementById('reset').onclick=()=>{q.value=v.value=d.value='';s.value=sm.value='kana';render()};results.addEventListener('click',e=>{const r=e.target.closest('.row');if(r)openSong(r.dataset.id)});results.addEventListener('keydown',e=>{const r=e.target.closest('.row');if(r&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openSong(r.dataset.id)}});document.getElementById('close').onclick=()=>{detail.close();history.replaceState(null,'',location.pathname)};detail.addEventListener('click',e=>{if(e.target===detail)detail.close()});load().catch(()=>{status.textContent='読み込みに失敗しました'});
</script></body></html>`;

const songSelect=`SELECT w.id,w.title,w.title_kana,w.lyricist,w.composer,w.description,e.arranger,e.voicing,e.accompaniment,e.duration_seconds,e.difficulty,e.publisher,e.source_url,e.verification_status FROM works w JOIN editions e ON e.work_id=w.id`;
function json(data:unknown,status=200){return Response.json(data,{status,headers:{'cache-control':'no-store'}})}
async function seedExtra(db:D1Database){const existing=await db.prepare("SELECT COUNT(*) AS c FROM works WHERE id LIKE 'extra-%'").first<{c:number}>();if(Number(existing?.c||0)>=150)return;const songs=extraSongData.split('\n').map((line,i)=>{const [title,voicing,difficulty]=line.split('|');return{id:'extra-'+String(i+1).padStart(3,'0'),title,voicing,difficulty:Number(difficulty)}});for(let i=0;i<songs.length;i+=20){const statements=[];for(const x of songs.slice(i,i+20)){statements.push(db.prepare('INSERT OR IGNORE INTO works (id,title,title_kana,lyricist,composer,published) VALUES (?,?,?,?,?,1)').bind(x.id,x.title,x.title,null,''));statements.push(db.prepare("INSERT INTO editions (work_id,voicing,accompaniment,difficulty,verification_status) SELECT ?,?,?,?,'unverified' WHERE NOT EXISTS (SELECT 1 FROM editions WHERE work_id=?)").bind(x.id,x.voicing,'ピアノ',x.difficulty,x.id))}await db.batch(statements)}}
export default{async fetch(request:Request,env:Env):Promise<Response>{const url=new URL(request.url);if(url.pathname==='/'&&request.method==='GET')return new Response(page,{headers:{'content-type':'text/html;charset=UTF-8','cache-control':'public,max-age=120'}});if(url.pathname==='/api/setup/seed-extra'&&request.method==='POST'){try{await seedExtra(env.DB);return json({ok:true})}catch(error){return json({ok:false,error:String(error)},500)}}if(url.pathname==='/api/health'){try{const row=await env.DB.prepare('SELECT COUNT(*) AS songs FROM works WHERE published=1').first();return json({ok:true,songs:Number(row?.songs||0)})}catch(error){return json({ok:false,error:String(error)},500)}}if(url.pathname==='/api/songs'){try{const result=await env.DB.prepare(songSelect+' WHERE w.published=1 ORDER BY w.title_kana LIMIT 500').all();return json(result.results)}catch(error){return json({error:'Database query failed',detail:String(error)},500)}}const match=url.pathname.match(/^\/api\/songs\/([A-Za-z0-9_-]+)$/);if(match){const song=await env.DB.prepare(songSelect+' WHERE w.published=1 AND w.id=? LIMIT 1').bind(match[1]).first();return song?json(song):json({error:'Song not found'},404)}return json({error:'Not found'},404)}};